using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CalmCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/CalmCustomDescription", order = 0)]
public class CalmCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CalmAction calmAction = battleAction as CalmAction;
		return Smart.Format(base.localizationManager.GetLocalizedEndTurnRemainDiceChantText().Replace(" {0} ", "").Replace(" {0}", "")
			.Replace("{0} ", "")
			.Replace("{0}", "")
			.Replace("{1}", "{0}"), calmAction.BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese()) + "\n" + GetRawLocalizedDescription(battleAction);
	}
}
